  slack_bot_token:        get('SLACK_BOT_TOKEN','slack_bot_token'),
  twitter_bearer_token:   get('TWITTER_BEARER_TOKEN','twitter_bearer_token'),
  facebook_access_token:  get('FACEBOOK_ACCESS_TOKEN','facebook_access_token'),
  linkedin_access_token:  get('LINKEDIN_ACCESS_TOKEN','linkedin_access_token'),
  spotify_access_token:   get('SPOTIFY_ACCESS_TOKEN','spotify_access_token'),
  youtube_api_key:        get('YOUTUBE_API_KEY','youtube_api_key'),
  line_notify_token:      get('LINE_NOTIFY_TOKEN','line_notify_token'),
  google_maps_key:        get('GOOGLE_MAPS_API_KEY','google_maps_key'),
  brave_api_key:          get('BRAVE_API_KEY','brave_api_key'),
  openweathermap_key:     get('OPENWEATHERMAP_API_KEY','openweathermap_key'),
  fal_api_key:            get('FAL_API_KEY','fal_api_key'),
  elevenlabs_api_key:     get('ELEVENLABS_API_KEY','elevenlabs_api_key'),
  elevenlabs_voice_id:    get('ELEVENLABS_VOICE_ID','elevenlabs_voice_id'),
  unsplash_access_key:    get('UNSPLASH_ACCESS_KEY','unsplash_access_key'),
  nutritionix_app_id:     get('NUTRITIONIX_APP_ID','nutritionix_app_id'),
  nutritionix_api_key:    get('NUTRITIONIX_API_KEY','nutritionix_api_key'),
  finnhub_api_key:        get('FINNHUB_API_KEY','finnhub_api_key'),
  ha_url:                 get('HOME_ASSISTANT_URL','ha_url'),
  ha_token:               get('HOME_ASSISTANT_TOKEN','ha_token'),
  sonos_api_url:          get('SONOS_HTTP_API_URL','sonos_api_url'),
  lastfm_api_key:         get('LASTFM_API_KEY','lastfm_api_key'),
  lastfm_username:        get('LASTFM_USERNAME','lastfm_username'),
  lastfm_session_key:     get('LASTFM_SESSION_KEY','lastfm_session_key'),
  internal_auth_token:    get('INTERNAL_AUTH_TOKEN','internal_auth_token'),
  n8n_base_url:           get('N8N_BASE_URL','n8n_base_url'),
  database_url:           prev.databaseUrl || get('DATABASE_URL','database_url'),
  github_token:           get('GITHUB_TOKEN','github_token')
};

// OpenRouter keys for LLM fallback
const userOrKey  = t.openrouter_access_token || '';
const sysOrKey   = process.env.OPENROUTER_API_KEY || '';
const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';

// ── USER_CONTEXT (consistent with WF3-A/B v5) ─────────────────
const userContextParts = [];
if (p.name) userContextParts.push(`Name: ${p.name}`);
if (p.interests?.length > 0) userContextParts.push(`Interests: ${p.interests.join(', ')}`);
if (p.personality_notes) userContextParts.push(`Personality: ${p.personality_notes}`);
if (p.key_facts?.length > 0) {
  userContextParts.push(`Key Facts:\n${p.key_facts.map(f => `  - ${f}`).join('\n')}`);
}
if (p.physical_stats && Object.keys(p.physical_stats).length > 0) {
  const stats = Object.entries(p.physical_stats).map(([k,v]) => `${k}: ${v}`).join(', ');
  userContextParts.push(`Physical Stats: ${stats}`);
}
if (p.ethical_profile) {
  const ep = p.ethical_profile;
  userContextParts.push(
    `Growth Stage: ${ep.growth_stage} (${ep.growth_stage_label})` +
    (ep.top_strengths?.length > 0 ? ` | Strengths: ${ep.top_strengths.join(', ')}` : '')
  );
}
if (p.relevant_memories?.length > 0) {
  const memStr = p.relevant_memories.map(m => `  [${m.type}]: ${m.summary}`).join('\n');
  userContextParts.push(`Recent Memories (static snapshot):\n${memStr}`);
}

const USER_CONTEXT = userContextParts.length > 0
  ? `\n\n## WHAT I KNOW ABOUT YOU:\n${userContextParts.join('\n')}\n`
  : '';

// ── GROWTH_GUIDANCE ───────────────────────────────────────────
const stage = p.ethical_profile?.growth_stage || 2;
const GROWTH_GUIDANCE = {
  1: 'User is new to finance — use simple language, explain concepts, avoid jargon',
  2: 'User is developing — guide step by step with examples and calculations',
  3: 'User is growing — challenge with deeper strategies, discuss tradeoffs',
  4: 'User is advanced — peer-level discussion, explore complex instruments',
  5: 'User is expert — minimal guidance, focus on nuanced analysis'
}[stage] || '';

const connected = Object.entries(creds).filter(([k,v]) => v).map(([k]) => k);

console.log('[Load Credentials v5 Career]', {
  userId: prev.userId?.substring(0,8)+'...',
  connected: connected.length,
  lang,
  hasUserKey: !!userOrKey,
  growthStage: stage
});

return {
  json: {
    ...prev,
    credentials: creds,
    lang, i18n,
    USER_CONTEXT,
    GROWTH_GUIDANCE,
    stage,
    userOrKey, sysOrKey,
    PAID_MODEL, FREE_MODEL,
    _connected: connected,
    _persona: p
  }
};

const input = JSON.parse($input.first().json.query || '{}');
const query = input.query || input.q || '';
const limit = input.limit || 3;
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';
const persona = ctx._persona || ctx.persona || {};
const tokens  = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl)   return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: 'Query too short', memories: [] } };
if (!embedKey) return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) return { json: { error: `Embed failed: ${embedRes.status}`, memories: [] } };
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding) return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2 AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content: r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata: r.metadata || {},
    date: new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0) return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input = JSON.parse($input.first().json.query || '{}');
const type   = (input.type || input.data_type || 'quote').toLowerCase();
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const apiKey = creds.finnhub_api_key || process.env.FINNHUB_API_KEY || '';
const BASE   = 'https://finnhub.io/api/v1';

try {
  if (type === 'quote') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const res  = await fetch(`${BASE}/quote?symbol=${symbol}&token=${apiKey}`);
    const data = await res.json();
    if (data.error) return { json: { error: data.error } };
    return { json: {
      symbol, currentPrice: data.c, change: data.d, changePercent: data.dp,
      high: data.h, low: data.l, open: data.o, prevClose: data.pc,
      timestamp: new Date().toISOString(),
      message: `${symbol}: $${data.c} (${data.dp > 0 ? '+' : ''}${data.dp?.toFixed(2)}%)`
    }};
  }
  if (type === 'news') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const today = new Date().toISOString().split('T')[0];
    const week  = new Date(Date.now()-7*86400000).toISOString().split('T')[0];
    const res   = await fetch(`${BASE}/company-news?symbol=${symbol}&from=${week}&to=${today}&token=${apiKey}`);
    const news  = await res.json();
    const top5  = (news||[]).slice(0,5).map(n => ({ headline: n.headline, summary: n.summary?.slice(0,200), url: n.url, date: new Date(n.datetime*1000).toLocaleDateString() }));
    return { json: { symbol, news: top5, count: top5.length } };
  }
  if (type === 'profile') {
    const symbol = (input.symbol || '').toUpperCase();
    if (!symbol) return { json: { error: i18n.symbol_required || 'symbol required' } };
    if (!apiKey) return { json: { error: `Finnhub API ${i18n.not_connected}`, help: i18n.configure } };
    const res  = await fetch(`${BASE}/stock/profile2?symbol=${symbol}&token=${apiKey}`);
    const data = await res.json();
    return { json: { symbol, name: data.name, industry: data.finnhubIndustry, country: data.country, marketCap: data.marketCapitalization, logo: data.logo } };
  }
  if (type === 'crypto') {
    const coinId = input.coin_id || input.symbol || 'bitcoin';
    const res = await fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${coinId}&vs_currencies=usd,thb&include_24hr_change=true&include_market_cap=true`);
    const data = await res.json();
    if (!data[coinId]) return { json: { error: `Coin '${coinId}' not found. Try: bitcoin, ethereum, solana` } };
    return { json: { coin: coinId, ...data[coinId], timestamp: new Date().toISOString() } };
  }
  if (type === 'fx_rates') {
    const base = (input.base || 'USD').toUpperCase();
    const res  = await fetch(`https://api.fxratesapi.com/latest?base=${base}&currencies=THB,EUR,JPY,GBP,SGD,CNY,KRW`);
    const data = await res.json();
    return { json: { base, rates: data.rates, date: data.date } };
  }
  return { json: { error: `Unknown type: ${type}. Use: quote, news, profile, crypto, fx_rates` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input  = JSON.parse($input.first().json.query || '{}');
const from   = (input.from || 'USD').toUpperCase();
const to     = (input.to || 'THB').toUpperCase();
const amount = parseFloat(input.amount || 1);
const i18n   = $('Load Credentials').first().json.i18n || {};

try {
  const res  = await fetch(`https://api.exchangerate-api.com/v4/latest/${from}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const rate = data.rates[to];
  if (!rate) return { json: { error: `Currency ${to} not found` } };
  const converted = (amount * rate).toFixed(2);
  return { json: {
    from, to, amount, rate: rate.toFixed(6),
    converted: parseFloat(converted),
    message: `${amount} ${from} = ${converted} ${to} (rate: ${rate.toFixed(4)})`,
    date: data.date
  }};
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input  = JSON.parse($input.first().json.query || '{}');
const action = (input.action || 'add').toLowerCase();
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';

if (!dbUrl) return { json: { error: i18n.not_connected || 'Database not connected' } };

const { Pool } = require('pg');
const pool = new Pool({ connectionString: dbUrl });
try {
  if (action === 'add') {
    const type     = (input.type || 'expense').toLowerCase();
    const amount   = parseFloat(input.amount || 0);
    const category = input.category || 'general';
    const note     = input.note || '';
    const currency = input.currency || 'THB';
    if (amount <= 0) return { json: { error: i18n.amount_required || 'Valid amount required' } };
    await pool.query(
      `INSERT INTO user_data_schema.budget_entries (user_id, type, amount, category, note, currency, created_at)
       VALUES ($1, $2, $3, $4, $5, $6, NOW())`,
      [userId, type, amount, category, note, currency]
    );
    await pool.end();
    return { json: { success: true, type, amount, category, currency, message: `${type === 'income' ? '💰' : '💸'} ${type} ${amount} ${currency} recorded` } };
  } else if (action === 'summary') {
    const months = input.months || 1;
    const result = await pool.query(
      `SELECT type, SUM(amount) as total, currency FROM user_data_schema.budget_entries
       WHERE user_id = $1 AND created_at >= NOW() - INTERVAL '${months} months'
       GROUP BY type, currency`,
      [userId]
    );
    await pool.end();
    const income  = result.rows.filter(r => r.type === 'income').reduce((s,r) => s + parseFloat(r.total), 0);
    const expense = result.rows.filter(r => r.type === 'expense').reduce((s,r) => s + parseFloat(r.total), 0);
    return { json: { income, expense, balance: income - expense, rows: result.rows, period: `${months} month(s)` } };
  } else if (action === 'categories') {
    const result = await pool.query(
      `SELECT category, SUM(amount) as total, COUNT(*) as count FROM user_data_schema.budget_entries
       WHERE user_id = $1 AND type = 'expense' AND created_at >= NOW() - INTERVAL '1 month'
       GROUP BY category ORDER BY total DESC`,
      [userId]
    );
    await pool.end();
    return { json: { categories: result.rows } };
  }
  await pool.end();
  return { json: { error: 'Unknown action. Use: add | summary | categories' } };
} catch(err) {
  try { await pool.end(); } catch(e) {}
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx  = $('Load Credentials').first().json;
const i18n = ctx.i18n || {};
const lang = ctx.lang || 'th';
const type = (input.calc_type || 'thai_income_tax').toLowerCase();

const disclaimers = {
  th: '⚠️ ประมาณการเบื้องต้น กรุณาปรึกษานักบัญชีหรือสรรพากร',
  en: '⚠️ Preliminary estimate only. Please consult an accountant or tax authority.',
  ja: '⚠️ 概算のみです。会計士または税務機関にご相談ください。',
  zh: '⚠️ 仅为初步估算。请咨询会计师或税务机关。'
};
const disclaimer = disclaimers[lang] || disclaimers['en'];

try {
  if (type === 'thai_income_tax') {
    const income      = parseFloat(input.annual_income || 0);
    const extraDeduct = parseFloat(input.deductions || 0);
    const personalDeduct = 60000;
    const ssoDeduct  = Math.min(income * 0.05, 9000);
    const totalDeduct = personalDeduct + ssoDeduct + extraDeduct;
    const taxable    = Math.max(0, income - totalDeduct);
    const brackets   = [
      [0,150000,0],[150001,300000,0.05],[300001,500000,0.10],
      [500001,750000,0.15],[750001,1000000,0.20],[1000001,2000000,0.25],
      [2000001,5000000,0.30],[5000001,Infinity,0.35]
    ];
    let tax = 0;
    for (const [min, max, rate] of brackets) {
      if (taxable <= min) break;
      tax += (Math.min(taxable, max) - min) * rate;
    }
    return { json: {
      calc_type: type, annual_income: income,
      total_deductions: totalDeduct, taxable_income: taxable,
      estimated_tax: Math.round(tax),
      effective_rate_pct: income > 0 ? Math.round(tax/income*1000)/10 : 0,
      monthly_withholding: Math.round(tax/12),
      disclaimer
    }};
  }
  if (type === 'compound_interest') {
    const p = parseFloat(input.principal || 0);
    const r = parseFloat(input.rate_pct || 0) / 100;
    const n = parseInt(input.years || 1);
    const final = p * Math.pow(1 + r, n);
    return { json: {
      calc_type: type, principal: p, rate_pct: r*100, years: n,
      final_amount: Math.round(final),
      gain: Math.round(final - p),
      gain_pct: Math.round((final/p - 1)*1000)/10,
      disclaimer
    }};
  }
  if (type === 'loan_payment') {
    const p = parseFloat(input.principal || 0);
    const r = parseFloat(input.annual_rate_pct || 0) / 100 / 12;
    const n = parseInt(input.years || 1) * 12;
    const pmt = r === 0 ? p/n : p * (r * Math.pow(1+r,n)) / (Math.pow(1+r,n) - 1);
    return { json: {
      calc_type: type, principal: p,
      monthly_payment: Math.round(pmt),
      total_paid: Math.round(pmt*n),
      total_interest: Math.round(pmt*n - p),
      disclaimer
    }};
  }
  if (type === 'savings_goal') {
    const goal    = parseFloat(input.goal || 0);
    const initial = parseFloat(input.initial || 0);
    const monthly = parseFloat(input.monthly_savings || 0);
    const r       = parseFloat(input.rate_pct || 0) / 100 / 12;
    let balance = initial, months = 0;
    while (balance < goal && months < 1200) { balance = balance * (1 + r) + monthly; months++; }
    return { json: {
      calc_type: type, goal, initial, monthly_savings: monthly,
      months_to_goal: months,
      years_to_goal: Math.round(months/12*10)/10,
      achievable: months < 1200,
      disclaimer
    }};
  }
  return { json: { error: `Unknown calc_type: ${type}. Use: thai_income_tax, compound_interest, loan_payment, savings_goal` } };
} catch(e) {
  return { json: { error: e.message } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx   = $('Load Credentials').first().json;
const i18n  = ctx.i18n || {};
const lang  = ctx.lang || 'th';
