  `──────────────────────────────────`,
  `${lb.bank}: ${input.bank_account || lb.bank_placeholder}`
].filter(l => l !== null).join('\n');

return { json: { invoice_number: invoiceNum, subtotal, vat, withholding_tax: wht, total, currency: lb.currency, invoice_text: invoiceText } };

